files.eww.scss:
$bg: #2b3339;
$fg: #d3c6aa;
$accent: #a7c080;
$gray: #4b5652;

* { 
  all: unset; 
  font-family: "JetBrainsMono Nerd Font"; 
  font-size: 13px; 
}

// УБИВАЕМ РАМКИ КНОПОК
button {
  background: none !important;
  background-image: none !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0;
  margin: 0;
}

.bar-container {
  background-color: transparent;
}

/* Модули-островки */
.module-ws, .module-win, .module-stats {
  background-color: $bg;
  border: 1px solid #3c4841;
  border-radius: 12px;
  padding: 4px 12px;
}

/* Воркспейсы (Точки) */
.active { color: $accent; margin: 0 4px; }
.inactive { color: $gray; margin: 0 4px; }

/* Окно */
.module-win { color: $fg; font-weight: bold; }

/* Статистика */
.module-stats {
  label { margin: 0 5px; }
  .gpu { color: #dbbc7f; }
  .cpu { color: #e67e80; }
  .ram { color: #d699b6; }
  .vol { color: #7fbbb3; }
  .layout { color: $accent; font-weight: bold; }
  .time { color: $fg; font-weight: bold; margin-left: 5px; }
}

files.scripts/layout.sh:
#!/bin/bash
handle() {
  hyprctl devices -j | jq -r '.keyboards[] | select(.main == true).active_keymap' | cut -c1-2 | tr '[:upper:]' '[:lower:]'
}

handle # Начальное значение
socat -u UNIX-CONNECT:$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/.socket2.sock - | while read -r line; do
  case $line in activelayout*) handle ;; esac
done

files.scripts/workspaces.sh:
#!/bin/bash
generate() {
  active=$(hyprctl monitors -j | jq '.[] | select(.focused == true) | .activeWorkspace.id')
  seq 1 10 | jq -nc --arg active "$active" '[range(1;11) | {id: ., active: (. == ($active|tonumber))}]'
}
generate
socat -u UNIX-CONNECT:$XDG_RUNTIME_DIR/hypr/$HYPRLAND_INSTANCE_SIGNATURE/.socket2.sock - | while read -r line; do
  case $line in workspace*) generate ;; esac
done
